def binary_search(items, target):
    lo, hi = 0, len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        elif items[mid] > target:
            hi = mid - 1
        else:
            lo = mid + 1
    return -1
```

